package mx.com.mesaregia.ordenes.domain.entity; import jakarta.persistence.*; import lombok.*; import mx.com.mesaregia.ordenes.domain.enums.EstadoOutbox; import java.time.LocalDateTime; @Entity @Table(name="integration_outbox") @Getter @Setter @NoArgsConstructor public class IntegrationOutbox {@Id @GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="id_outbox")Long id;@Column(name="event_id",nullable=false,unique=true,length=80)String eventId;@Column(nullable=false,length=100)String tipo;@Lob @Column(nullable=false,columnDefinition="LONGTEXT")String payload;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)EstadoOutbox estado=EstadoOutbox.PENDIENTE;@Column(nullable=false)Integer intentos=0;@Column(name="proximo_intento",nullable=false)LocalDateTime proximoIntento=LocalDateTime.now();@Column(name="ultimo_error",length=1000)String ultimoError;@Column(name="creado_en",insertable=false,updatable=false)LocalDateTime creadoEn;@Column(name="enviado_en")LocalDateTime enviadoEn;}